[Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12
function Test-WebViewRuntime {
 foreach($key in @('HKLM:\SOFTWARE\WOW6432Node\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}','HKCU:\SOFTWARE\Microsoft\EdgeUpdate\Clients\{F3017226-FE2A-4295-8BDF-00C3A9A7E4C5}')){$v=(Get-ItemProperty -LiteralPath $key -Name pv -ErrorAction SilentlyContinue).pv;$parsed=$null;if([version]::TryParse($v,[ref]$parsed)-and $parsed -gt [version]'0.0.0.0'){return $true}};return $false
}
if(Test-WebViewRuntime){exit 0}
$dir=Join-Path $env:LOCALAPPDATA ('InstallStreet\WebView2Setup\'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory -Path $dir -Force|Out-Null;$file=Join-Path $dir 'MicrosoftEdgeWebview2Setup.exe'
try{Write-Output 'Downloading Microsoft WebView2 Runtime...';Invoke-WebRequest -UseBasicParsing -Uri 'https://go.microsoft.com/fwlink/p/?LinkId=2124703' -OutFile $file -TimeoutSec 180;$sig=Get-AuthenticodeSignature -LiteralPath $file;if($sig.Status-ne 'Valid'-or $sig.SignerCertificate.Subject-notmatch '(^|,\s*)O=Microsoft Corporation(,|$)'){throw 'WebView2 installer signature is not valid Microsoft code.'};Write-Output 'Installing Microsoft WebView2 Runtime...';$p=Start-Process -FilePath $file -ArgumentList '/silent /install' -WindowStyle Hidden -PassThru -Wait;if($p.ExitCode-notin @(0,3010)){throw "WebView2 setup failed ($($p.ExitCode)). Retry the installation."};if(!(Test-WebViewRuntime)){throw 'WebView2 is still missing after setup. Restart Windows if requested, then retry.'};Remove-Item -LiteralPath $file -Force;Write-Output 'WebView2 Runtime is ready.'}catch{[Console]::Error.WriteLine($_.Exception.Message);exit 1}
